import { useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import { Check, ChevronDown, CirclePlus, Code2, Copy, Crown, Download, Eye, FileText, Gamepad2, Hash, Headphones, Image, Link2, LogIn, LogOut, Maximize2, Mic, MicOff, Minimize2, Minus, MonitorUp, PhoneOff, Plus, Quote, Scissors, Search, Send, Settings, Smile, Square, Strikethrough, UserPlus, Users, Volume2, VolumeX, X } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { request, serverUrl, socket, uploadFile, type AuthPayload, type Channel, type ChatMessage, type Space, type User } from './api';
import { ScreenSession, type RemoteMedia, type ShareProfile } from './media';
import './fixes.css';

const TOKEN_KEY='echodeck.session';
const LAST_SPACE_KEY='poio.last-space';
const channelIcon=(kind:string)=>kind==='voice'?<Volume2 size={17}/>:<Hash size={17}/>;
const spaceInitial=(name:string)=>(Array.from(name.trim())[0]??'?').toLocaleUpperCase('en-US');
const electronBridge=()=>{const bridge=window.echodeck;if(!bridge?.mumble)throw new Error('Electron 桥接未加载，请安装 POIO 0.2.0 或更高版本后重启客户端');return bridge};
type ScreenshotCapture={dataUrl:string;width:number;height:number;displayName:string};
type QueuedScreenshot={file:File;url:string};

export default function App(){
  const [user,setUser]=useState<User>(); const [spaces,setSpaces]=useState<Space[]>([]); const [spaceId,setSpaceId]=useState(''); const [channelId,setChannelId]=useState('');
  const [messages,setMessages]=useState<ChatMessage[]>([]); const [body,setBody]=useState(''); const [error,setError]=useState(''); const errorTimer=useRef(0); const lastError=useRef({message:'',time:0}); const [loading,setLoading]=useState(true); const [uploading,setUploading]=useState(false); const [dropActive,setDropActive]=useState(false); const [imagePreview,setImagePreview]=useState<{url:string;name:string}>(); const fileRef=useRef<HTMLInputElement>(null); const avatarRef=useRef<HTMLInputElement>(null); const composerInputRef=useRef<HTMLTextAreaElement>(null); const messageListRef=useRef<HTMLDivElement>(null); const messageFeedRef=useRef<HTMLDivElement>(null); const stickToLatestRef=useRef(true); const [messageAtBottom,setMessageAtBottom]=useState(true);
  const [screenshot,setScreenshot]=useState<ScreenshotCapture>(); const [pendingScreenshot,setPendingScreenshot]=useState<QueuedScreenshot>(); const [composerExpanded,setComposerExpanded]=useState(false); const [composerPreview,setComposerPreview]=useState(false); const [avatarUploading,setAvatarUploading]=useState(false);
  const [voiceChannel,setVoiceChannel]=useState(''); const [joiningVoiceChannel,setJoiningVoiceChannel]=useState(''); const [muted,setMuted]=useState(false); const [deafened,setDeafened]=useState(false); const [micLevel,setMicLevel]=useState(0); const [inputVolume,setInputVolume]=useState(100); const [outputVolume,setOutputVolume]=useState(100); const volumeTimer=useRef(0); const [memberVolumes,setMemberVolumes]=useState<Record<string,number>>({}); const [talkingMembers,setTalkingMembers]=useState<Record<string,boolean>>({}); const memberVolumeTimers=useRef<Record<string,number>>({}); const [voiceMembers,setVoiceMembers]=useState<Record<string,User[]>>({}); const [remoteMedia,setRemoteMedia]=useState<RemoteMedia[]>([]);
  const voiceJoinEpoch=useRef(0);
  const [shareOpen,setShareOpen]=useState(false); const [sources,setSources]=useState<Array<any>>([]); const [shareProfile,setShareProfile]=useState<ShareProfile>('hd'); const [shareAudio,setShareAudio]=useState(false); const [localShare,setLocalShare]=useState<MediaStream>();
  const [settingsOpen,setSettingsOpen]=useState(false); const [audioDevices,setAudioDevices]=useState<MumbleAudioDevices>(); const [settingsBusy,setSettingsBusy]=useState(false);
  const [spaceDialog,setSpaceDialog]=useState<'create'|'join'>(); const [channelDialog,setChannelDialog]=useState<'text'|'voice'>(); const [invite,setInvite]=useState<{code:string;spaceName:string;expiresAt:number}>(); const [spaceMembers,setSpaceMembers]=useState<Array<User&{role:string}>>([]); const [onlineUserIds,setOnlineUserIds]=useState<string[]>([]); const [membersOpen,setMembersOpen]=useState(true); const [emojiOpen,setEmojiOpen]=useState(false); const [accountOpen,setAccountOpen]=useState(false); const [channelQuery,setChannelQuery]=useState(''); const channelSearchRef=useRef<HTMLInputElement>(null);
  const [updateStatus,setUpdateStatus]=useState<AppUpdateStatus>({state:'idle'});
  const [updateDialogOpen,setUpdateDialogOpen]=useState(false);
  const [mumbleState,setMumbleState]=useState<MumbleRuntimeState>({state:'disconnected'});
  const [unreadChannels,setUnreadChannels]=useState<Record<string,number>>({});
  const [reconnectEpoch,setReconnectEpoch]=useState(0);
  const screen=useMemo(()=>new ScreenSession(setRemoteMedia),[]);
  const currentSpace=spaces.find(s=>s.id===spaceId)??spaces[0]; const currentChannel=currentSpace?.channels.find(c=>c.id===channelId)??currentSpace?.channels[0];
  const onlineSet=new Set(onlineUserIds); const onlineMembers=spaceMembers.filter(member=>onlineSet.has(member.id)); const offlineMembers=spaceMembers.filter(member=>!onlineSet.has(member.id)); const visibleVoiceMembers=currentChannel?.kind==='voice'?(voiceMembers[currentChannel.id]??[]):[];

  useEffect(()=>{ const expired=()=>window.location.reload();window.addEventListener('poio:session-expired',expired);const token=localStorage.getItem(TOKEN_KEY); if(!token){setLoading(false);return()=>window.removeEventListener('poio:session-expired',expired);} request<AuthPayload>('auth:resume',{token}).then(applyAuth).catch(()=>localStorage.removeItem(TOKEN_KEY)).finally(()=>setLoading(false)); return()=>{window.removeEventListener('poio:session-expired',expired);screen.close()}; },[]);
  useEffect(()=>{const mumble=window.echodeck?.mumble;if(!mumble)return;void mumble.state().then(setMumbleState);return mumble.onState(setMumbleState)},[]);
  useEffect(()=>{const disconnected=()=>{screen.close();setLocalShare(undefined)};const restored=()=>setReconnectEpoch(value=>value+1);window.addEventListener('poio:socket-disconnected',disconnected);window.addEventListener('poio:session-restored',restored);return()=>{window.removeEventListener('poio:socket-disconnected',disconnected);window.removeEventListener('poio:session-restored',restored)}},[screen]);
  useEffect(()=>{ const created=(channel:Channel)=>setSpaces(all=>all.map(s=>s.id===(channel as any).spaceId?{...s,channels:[...s.channels,channel]}:s)); socket.on('channel:created',created); return()=>{socket.off('channel:created',created)}; },[]);
  useEffect(()=>{ const presence=(event:{channelId:string;users:User[]})=>setVoiceMembers(all=>({...all,[event.channelId]:event.users})); socket.on('voice:presence',presence); return()=>{socket.off('voice:presence',presence)}; },[]);
  useEffect(()=>{const updated=(next:User)=>{setUser(current=>current?.id===next.id?next:current);setSpaceMembers(all=>all.map(member=>member.id===next.id?{...member,...next}:member));setVoiceMembers(all=>Object.fromEntries(Object.entries(all).map(([key,members])=>[key,members.map(member=>member.id===next.id?{...member,...next}:member)])));setMessages(all=>all.map(message=>message.userId===next.id?{...message,avatarUrl:next.avatarUrl}:message))};socket.on('user:updated',updated);return()=>{socket.off('user:updated',updated)}},[]);
  useEffect(()=>{if(!channelId||!user)return;let disposed=false;stickToLatestRef.current=true;setMessageAtBottom(true);setMessages([]);request('channel:watch',{channelId}).catch(showError);request<ChatMessage[]>('chat:history',{channelId}).then(value=>{if(!disposed)setMessages(value.slice(-500))}).catch(showError);const incoming=(m:ChatMessage)=>{if(!disposed&&m.channelId===channelId)setMessages(v=>[...v,m].slice(-500))};socket.on('chat:message',incoming);return()=>{disposed=true;socket.off('chat:message',incoming)}},[channelId,user,reconnectEpoch]);
  useLayoutEffect(()=>{const list=messageListRef.current;if(!list||!stickToLatestRef.current)return;list.scrollTop=list.scrollHeight;setMessageAtBottom(true)},[messages,channelId]);
  useEffect(()=>{const list=messageListRef.current;const feed=messageFeedRef.current;if(!list||!feed||typeof ResizeObserver==='undefined')return;let frame=0;const observer=new ResizeObserver(()=>{if(!stickToLatestRef.current)return;cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{list.scrollTop=list.scrollHeight;setMessageAtBottom(true)})});observer.observe(feed);observer.observe(list);return()=>{observer.disconnect();cancelAnimationFrame(frame)}},[user]);
  useLayoutEffect(()=>{const input=composerInputRef.current;if(!input)return;input.style.height='25px';const height=composerExpanded?Math.max(25,input.scrollHeight):Math.min(120,Math.max(25,input.scrollHeight));input.style.height=`${height}px`;input.style.overflowY=!composerExpanded&&input.scrollHeight>120?'auto':'hidden';if(!body)input.scrollTop=0},[body,composerExpanded,composerPreview]);
  useEffect(()=>{if(!reconnectEpoch||!voiceChannel)return;request<{channelId:string;users:User[]}>('voice:join',{channelId:voiceChannel}).then(presence=>setVoiceMembers(all=>({...all,[voiceChannel]:presence.users}))).catch(showError);screen.join(voiceChannel).catch(showError)},[reconnectEpoch,voiceChannel,screen]);
  useEffect(()=>{let disposed=false;let timer=0;const poll=async()=>{try{const level=await electronBridge().mumble.level();if(!disposed)setMicLevel(level)}catch{if(!disposed)setMicLevel(0)}finally{if(!disposed)timer=window.setTimeout(poll,90)}};if(voiceChannel&&!muted)void poll();else setMicLevel(0);return()=>{disposed=true;window.clearTimeout(timer)}},[voiceChannel,muted]);
  useEffect(()=>{if(!voiceChannel)return;void electronBridge().mumble.volumes().then(value=>{setInputVolume(value.input);setOutputVolume(value.output)}).catch(()=>{})},[voiceChannel]);
  useEffect(()=>{if(!voiceChannel){setMemberVolumes({});setTalkingMembers({});return}let disposed=false;let timer=0;const poll=async()=>{try{const users=await electronBridge().mumble.users();if(!disposed){setMemberVolumes(current=>{const next={...current};for(const item of users)next[item.username]=item.volume;return next});setTalkingMembers(Object.fromEntries(users.map(item=>[item.username,item.talking])))}}catch{}finally{if(!disposed)timer=window.setTimeout(poll,220)}};void poll();return()=>{disposed=true;window.clearTimeout(timer)}},[voiceChannel]);
  useEffect(()=>{if(!spaceId||!user)return;request<Array<User&{role:string}>>('space:members',{spaceId}).then(setSpaceMembers).catch(showError)},[spaceId,user,reconnectEpoch]);
  useEffect(()=>{const joined=(event:{spaceId:string;user:User})=>{if(event.spaceId===spaceId)setSpaceMembers(all=>all.some(member=>member.id===event.user.id)?all:[...all,{...event.user,role:'member'}])};socket.on('space:memberJoined',joined);return()=>{socket.off('space:memberJoined',joined)}},[spaceId]);
  useEffect(()=>{if(!spaceId||!user)return;request<string[]>('space:presence',{spaceId}).then(setOnlineUserIds).catch(showError);const presence=(event:{spaceId:string;userIds:string[]})=>{if(event.spaceId===spaceId)setOnlineUserIds(event.userIds)};socket.on('space:presence',presence);return()=>{socket.off('space:presence',presence)}},[spaceId,user,reconnectEpoch]);
  useEffect(()=>{const activity=(event:{channelId:string;userId:string})=>{if(event.channelId===channelId)return;if(!spaces.some(space=>space.channels.some(channel=>channel.id===event.channelId)))return;setUnreadChannels(current=>({...current,[event.channelId]:Math.min(99,(current[event.channelId]??0)+1)}))};socket.on('chat:activity',activity);return()=>{socket.off('chat:activity',activity)}},[channelId,spaces]);
  useEffect(()=>{const key=(event:KeyboardEvent)=>{if(event.ctrlKey&&event.key.toLowerCase()==='k'){event.preventDefault();channelSearchRef.current?.focus()}};window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key)},[]);
  useEffect(()=>{const updater=window.echodeck?.update;if(!updater)return;const receive=(status:AppUpdateStatus)=>{setUpdateStatus(status);if(['available','downloaded'].includes(status.state))setUpdateDialogOpen(true)};void updater.status().then(receive);return updater.onStatus(receive)},[]);
  useEffect(()=>()=>{if(pendingScreenshot)URL.revokeObjectURL(pendingScreenshot.url)},[pendingScreenshot]);
  const applyAuth=(result:AuthPayload)=>{localStorage.setItem(TOKEN_KEY,result.token);setUser(result.user);setSpaces(result.bootstrap);const remembered=localStorage.getItem(LAST_SPACE_KEY);const s=result.bootstrap.find(space=>space.id===remembered)??result.bootstrap[0];setSpaceId(s?.id??'');setChannelId(s?.channels[0]?.id??'');if(s)localStorage.setItem(LAST_SPACE_KEY,s.id)};
  const showError=(e:unknown)=>{const message=e instanceof Error?e.message:'发生错误';const now=Date.now();if(lastError.current.message===message&&now-lastError.current.time<10000)return;lastError.current={message,time:now};window.clearTimeout(errorTimer.current);setError(message);errorTimer.current=window.setTimeout(()=>setError(''),3500)};
  const loadAudioDevices=async()=>{if(!voiceChannel){setAudioDevices(undefined);return}setSettingsBusy(true);try{setAudioDevices(await electronBridge().mumble.devices())}catch(e){showError(e)}finally{setSettingsBusy(false)}};
  const loadVoiceControls=async()=>{if(!voiceChannel)return;try{const [devices,volumes]=await Promise.all([electronBridge().mumble.devices(),electronBridge().mumble.volumes()]);setAudioDevices(devices);setInputVolume(volumes.input);setOutputVolume(volumes.output)}catch{}};
  if(loading)return <div className="boot"><div className="brand-mark">POIO</div><span>正在连接 POIO...</span></div>;
  if(!user)return <Auth onAuth={applyAuth} onError={showError}/>;

  const selectChannel=async(channel:Channel)=>{setChannelId(channel.id);setUnreadChannels(current=>({...current,[channel.id]:0}));if(channel.kind==='voice'){const epoch=++voiceJoinEpoch.current;setJoiningVoiceChannel(channel.id);try{const connection=await request<{host:string;port:number;username:string;password:string;channelName:string}>('voice:credentials',{channelId:channel.id});if(epoch!==voiceJoinEpoch.current)return;await electronBridge().mumble.connect(connection);if(epoch!==voiceJoinEpoch.current)return;const presence=await request<{channelId:string;users:User[]}>('voice:join',{channelId:channel.id});if(epoch!==voiceJoinEpoch.current)return;setVoiceMembers(all=>({...all,[channel.id]:presence.users}));setVoiceChannel(channel.id);setJoiningVoiceChannel('');setMuted(false);setDeafened(false);try{await screen.join(channel.id)}catch(e){if(epoch===voiceJoinEpoch.current)showError(e)}}catch(e){if(epoch!==voiceJoinEpoch.current)return;setJoiningVoiceChannel('');screen.close();void electronBridge().mumble.disconnect();showError(e)}}};
  const send=async()=>{const text=body.trim();const queued=pendingScreenshot;if((!text&&!queued)||!currentChannel||uploading)return;const targetChannel=currentChannel;stickToLatestRef.current=true;setMessageAtBottom(true);if(queued)setUploading(true);try{const token=localStorage.getItem(TOKEN_KEY)??'';const attachment=queued?await uploadFile(queued.file,token):undefined;await request('chat:send',{channelId:targetChannel.id,body:text,attachment});setBody('');setPendingScreenshot(undefined);setComposerPreview(false)}catch(e){showError(e)}finally{if(queued)setUploading(false)}};
  const attach=async(file?:File)=>{if(!file||!currentChannel||uploading)return;if(file.size>50*1024*1024){showError(new Error('文件不能超过 50 MB'));return}const targetChannel=currentChannel;setUploading(true);try{const token=localStorage.getItem(TOKEN_KEY)??'';const attachment=await uploadFile(file,token);await request('chat:send',{channelId:targetChannel.id,body:'',attachment})}catch(e){showError(e)}finally{setUploading(false);if(fileRef.current)fileRef.current.value=''}};
  const captureScreenshot=async()=>{try{const bridge=window.echodeck;if(!bridge?.captureScreenshot)throw new Error('当前客户端不支持截图，请更新后重试');setEmojiOpen(false);setScreenshot(await bridge.captureScreenshot())}catch(e){showError(e)}};
  const queueScreenshot=(file:File)=>{setPendingScreenshot({file,url:URL.createObjectURL(file)});setScreenshot(undefined);setComposerPreview(false);window.setTimeout(()=>composerInputRef.current?.focus(),0)};
  const insertMarkdown=(before:string,after=before,placeholder='文字')=>{const input=composerInputRef.current;if(!input)return;const start=input.selectionStart;const end=input.selectionEnd;const selected=body.slice(start,end)||placeholder;const next=`${body.slice(0,start)}${before}${selected}${after}${body.slice(end)}`;setBody(next);window.setTimeout(()=>{input.focus();input.setSelectionRange(start+before.length,start+before.length+selected.length)},0)};
  const prefixMarkdown=(prefix:string)=>{const input=composerInputRef.current;if(!input)return;const start=input.selectionStart;const end=input.selectionEnd;const selected=body.slice(start,end)||'文字';const replacement=selected.split('\n').map(line=>`${prefix}${line}`).join('\n');setBody(`${body.slice(0,start)}${replacement}${body.slice(end)}`);window.setTimeout(()=>{input.focus();input.setSelectionRange(start,start+replacement.length)},0)};
  const updateAvatarFromFile=async(file?:File)=>{if(!file||avatarUploading)return;if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type)){showError(new Error('头像仅支持 PNG、JPG、GIF 或 WebP'));return}if(file.size>8*1024*1024){showError(new Error('头像不能超过 8 MB'));return}setAvatarUploading(true);try{const token=localStorage.getItem(TOKEN_KEY)??'';const uploaded=await uploadFile(file,token);const updated=await request<User>('user:avatar',{url:uploaded.url});setUser(updated);setAccountOpen(false)}catch(e){showError(e)}finally{setAvatarUploading(false);if(avatarRef.current)avatarRef.current.value=''}};
  const addChannel=async(name:string,kind:'text'|'voice')=>{if(!currentSpace)return;try{const c=await request<Channel>('channel:create',{spaceId:currentSpace.id,name,kind});setChannelId(c.id);setChannelDialog(undefined)}catch(e){showError(e)}};
  const openInvite=async()=>{if(!currentSpace)return;try{setInvite(await request('space:invite',{spaceId:currentSpace.id}))}catch(e){showError(e)}};
  const createSpaceFromDialog=async(name:string)=>{try{const space=await request<Space>('space:create',{name});setSpaces(all=>[...all,space]);setSpaceId(space.id);setChannelId(space.channels[0]?.id??'');localStorage.setItem(LAST_SPACE_KEY,space.id);setSpaceDialog(undefined)}catch(e){showError(e)}};
  const joinSpaceFromDialog=async(code:string)=>{try{const space=await request<Space>('space:join',{code});setSpaces(all=>all.some(item=>item.id===space.id)?all:[...all,space]);setSpaceId(space.id);setChannelId(space.channels[0]?.id??'');localStorage.setItem(LAST_SPACE_KEY,space.id);setSpaceDialog(undefined)}catch(e){showError(e)}};
  const openShare=async()=>{if(!voiceChannel){showError(new Error('请先加入语音频道'));return}try{setSources(await window.echodeck?.getDesktopSources()??[]);setShareOpen(true)}catch(e){showError(e)}};
  const startShare=async(sourceId:string)=>{try{if(!voiceChannel)throw new Error('请先加入语音频道');await screen.join(voiceChannel);const stream=await screen.share(sourceId,shareProfile,shareAudio);stream.getVideoTracks()[0]?.addEventListener('ended',()=>setLocalShare(current=>current===stream?undefined:current));setLocalShare(stream);setShareOpen(false)}catch(e){showError(e)}};
  const leaveVoiceChannel=async()=>{voiceJoinEpoch.current++;setJoiningVoiceChannel('');screen.close();localShare?.getTracks().forEach(track=>track.stop());setLocalShare(undefined);try{await request('voice:leave')}catch{}finally{await electronBridge().mumble.disconnect();setVoiceChannel('');setMuted(false);setDeafened(false);setMicLevel(0)}};
  const logout=async()=>{screen.close();localShare?.getTracks().forEach(track=>track.stop());try{await request('voice:leave')}catch{}try{await window.echodeck?.mumble.disconnect()}catch{}const token=localStorage.getItem(TOKEN_KEY);try{if(token)await request('auth:logout',{token})}catch{}finally{localStorage.removeItem(TOKEN_KEY);window.location.reload()}};
  const changeVolume=(kind:'input'|'output',value:number)=>{if(kind==='input')setInputVolume(value);else setOutputVolume(value);window.clearTimeout(volumeTimer.current);volumeTimer.current=window.setTimeout(()=>{void electronBridge().mumble.setVolume(kind,value).then(volumes=>{setInputVolume(volumes.input);setOutputVolume(volumes.output)}).catch(showError)},100)};
  const changeMemberVolume=(member:User,value:number)=>{const username=`ed_${member.id}`;setMemberVolumes(current=>({...current,[username]:value}));window.clearTimeout(memberVolumeTimers.current[username]);memberVolumeTimers.current[username]=window.setTimeout(()=>{void electronBridge().mumble.setUserVolume(username,value).then(saved=>setMemberVolumes(current=>({...current,[username]:saved}))).catch(showError)},100)};
  const selectQuickDevice=async(kind:'input'|'output',index:number)=>{try{const mumble=electronBridge().mumble;setAudioDevices(kind==='input'?await mumble.setInput(index):await mumble.setOutput(index))}catch(e){showError(e)}};
  const updateReady=updateStatus.state==='downloaded';
  const openOrCheckUpdate=()=>{if(['available','downloading','downloaded','error'].includes(updateStatus.state))setUpdateDialogOpen(true);else void window.echodeck?.update.check()};
  const titleUpdateVisible=['available','downloading','downloaded','error'].includes(updateStatus.state);
  const titleUpdateText=updateStatus.state==='available'?`发现 ${updateStatus.version??'新版本'}`:updateStatus.state==='downloading'?`更新下载中 ${updateStatus.percent??0}%`:updateStatus.state==='downloaded'?`${updateStatus.version??'新版本'} 已就绪`:'更新失败，点击重试';

  return <div className={`app-shell ${membersOpen?'':'members-hidden'}`}>
    <header className="titlebar"><div className="title-brand"><div className="poio-wordmark" aria-label="POIO">POIO</div><em>PREVIEW</em></div><div className="drag-region"/>{titleUpdateVisible&&<button className={`title-update ${updateReady?'ready':updateStatus.state==='error'?'failed':''}`} onClick={openOrCheckUpdate}><Download size={13}/><span>{titleUpdateText}</span>{updateReady&&<b>安装</b>}</button>}<button onClick={()=>window.echodeck?.window.minimize()}><Minus size={15}/></button><button onClick={()=>window.echodeck?.window.maximize()}><Square size={12}/></button><button className="close" onClick={()=>window.echodeck?.window.close()}><X size={16}/></button></header>
    <aside className="space-rail"><div className="home active" title="POIO"><div className="mini-mark">P</div></div><div className="rail-sep"/>{spaces.map(s=><button key={s.id} title={s.name} className={s.id===currentSpace?.id?'space active':'space'} onClick={()=>{const first=s.channels[0]?.id??'';setSpaceId(s.id);setChannelId(first);setUnreadChannels(current=>({...current,[first]:0}));setChannelQuery('');localStorage.setItem(LAST_SPACE_KEY,s.id)}}>{spaceInitial(s.name)}{s.channels.some(channel=>(unreadChannels[channel.id]??0)>0)&&<i className="space-unread"/>}<span>{s.name}</span></button>)}<button className="add-space" title="创建或加入社区" onClick={()=>setSpaceDialog('join')}><Plus/></button></aside>
    <aside className="channel-panel"><div className="space-head"><strong>{currentSpace?.name}</strong><button title="邀请好友" onClick={()=>void openInvite()}><UserPlus size={16}/></button></div><div className="channel-search"><Search size={15}/><input ref={channelSearchRef} value={channelQuery} onChange={event=>setChannelQuery(event.target.value)} placeholder="搜索频道"/><kbd>Ctrl K</kbd></div>
      <div className="channels"><ChannelGroup title="文字频道" onAdd={()=>setChannelDialog('text')}>{currentSpace?.channels.filter(c=>c.kind==='text'&&c.name.toLowerCase().includes(channelQuery.trim().toLowerCase())).map(c=><ChannelItem key={c.id} channel={c} active={c.id===channelId} voice={false} joining={false} unread={unreadChannels[c.id]??0} onClick={()=>selectChannel(c)}/>)}</ChannelGroup><ChannelGroup title="语音频道" onAdd={()=>setChannelDialog('voice')}>{currentSpace?.channels.filter(c=>c.kind==='voice'&&c.name.toLowerCase().includes(channelQuery.trim().toLowerCase())).map(c=><div className="voice-channel-entry" key={c.id}><ChannelItem channel={c} active={c.id===channelId} voice={c.id===voiceChannel} joining={c.id===joiningVoiceChannel} unread={unreadChannels[c.id]??0} onClick={()=>selectChannel(c)}/>{(voiceMembers[c.id]??[]).map(member=><VoiceMember key={member.id} user={member} self={member.id===user.id} connected={c.id===voiceChannel} talking={member.id===user.id?micLevel>.38&&!muted:talkingMembers[`ed_${member.id}`]===true} volume={memberVolumes[`ed_${member.id}`]??100} onVolume={value=>changeMemberVolume(member,value)}/>)}</div>)}</ChannelGroup></div>
      <div className={`voice-status ${mumbleState.state==='reconnecting'||mumbleState.state==='connecting'?'reconnecting':''}`}>{voiceChannel?<><div className="signal"><i/><i/><i/></div><div><b>{mumbleState.state==='reconnecting'?'Mumble 原生语音正在重连':mumbleState.state==='connecting'?'Mumble 原生语音正在连接':mumbleState.state==='error'?'Mumble 原生语音等待恢复':'Mumble 原生语音已连接'}</b><span>{mumbleState.state==='reconnecting'&&mumbleState.attempt?`第 ${mumbleState.attempt} 次尝试 · `:''}{currentSpace?.channels.find(c=>c.id===voiceChannel)?.name}</span></div><button onClick={()=>void leaveVoiceChannel()}><X size={17}/></button></>:<><Headphones size={19}/><span>尚未加入语音频道</span></>}</div>
      <div className="user-bar"><input ref={avatarRef} hidden type="file" accept="image/png,image/jpeg,image/webp,image/gif" onChange={event=>void updateAvatarFromFile(event.target.files?.[0])}/><div className="account-menu-wrap"><button className="account-trigger" title="账号菜单" onClick={()=>setAccountOpen(value=>!value)}><Avatar name={user.username} avatarUrl={user.avatarUrl}/><div className="user-identity"><b>{user.username}</b><span>{micLevel>.38&&!muted?'正在说话':'在线'}</span></div></button>{accountOpen&&<div className="account-popover"><div className="account-summary"><Avatar name={user.username} avatarUrl={user.avatarUrl}/><span><b>{user.username}</b><small>POIO 账号</small></span></div><button className="change-avatar-button" disabled={avatarUploading} onClick={()=>avatarRef.current?.click()}><Image size={15}/>{avatarUploading?'正在上传头像…':'更换头像（支持动态）'}</button><div className={`account-update ${updateReady?'ready':''}`}><Download size={15}/><span><b>客户端更新</b><small>{updateStatusText(updateStatus)}</small></span><button disabled={updateStatus.state==='checking'} onClick={openOrCheckUpdate}>{updateReady?'查看更新':updateStatus.state==='available'?'立即更新':updateStatus.state==='downloading'?`${updateStatus.percent??0}%`:updateStatus.state==='checking'?'检查中':'检查更新'}</button></div><button className="logout-button" onClick={()=>void logout()}><LogOut size={15}/>退出登录</button></div>}</div><div className="voice-control-wrap" onMouseEnter={()=>void loadVoiceControls()}><button disabled={!voiceChannel} className={`mic-control ${muted?'muted':micLevel>.38?'speaking':''}`} title={muted?'取消静音':'麦克风'} style={{boxShadow:muted?'none':`0 0 0 ${Math.round(micLevel*7)}px rgba(69,221,195,${Math.max(.08,micLevel*.45)})`}} onClick={async()=>{const next=!muted;try{await window.echodeck?.mumble.command(`MUTE ${next?1:0}`);setMuted(next)}catch(e){showError(e)}}}>{muted?<MicOff size={18}/>:<Mic size={18}/>}<i className="mic-mini-level" style={{height:`${Math.max(3,Math.round(micLevel*22))}px`}}/></button>{voiceChannel&&<AudioControlPopover kind="input" volume={inputVolume} devices={audioDevices?.inputs??[]} onVolume={value=>changeVolume('input',value)} onDevice={index=>void selectQuickDevice('input',index)} onSettings={()=>{setSettingsOpen(true);void loadAudioDevices()}}/>}</div><div className="voice-control-wrap output-control" onMouseEnter={()=>void loadVoiceControls()}><button disabled={!voiceChannel} className={deafened?'deafened':''} title={deafened?'取消关闭声音':'耳机/扬声器'} onClick={async()=>{const next=!deafened;try{await window.echodeck?.mumble.command(`DEAF ${next?1:0}`);setDeafened(next)}catch(e){showError(e)}}}><Headphones size={18}/></button>{voiceChannel&&<AudioControlPopover kind="output" volume={outputVolume} devices={audioDevices?.outputs??[]} onVolume={value=>changeVolume('output',value)} onDevice={index=>void selectQuickDevice('output',index)} onSettings={()=>{setSettingsOpen(true);void loadAudioDevices()}}/>}</div><button className="hangup" disabled={!voiceChannel} title="挂断语音" onClick={()=>void leaveVoiceChannel()}><PhoneOff size={17}/></button><button title="设置" onClick={()=>{setSettingsOpen(true);void loadAudioDevices()}}><Settings size={18}/></button></div>
    </aside>
    <main className="content"><div className="channel-head"><div>{channelIcon(currentChannel?.kind??'text')}<strong>{currentChannel?.name}</strong><span>{currentChannel?.kind==='voice'?'语音频道 · 可聊天与共享屏幕':'文字频道'}</span></div><div className="head-actions"><button onClick={openShare} className="share"><MonitorUp size={18}/>共享屏幕</button><button title="搜索频道" onClick={()=>channelSearchRef.current?.focus()}><Search size={18}/></button><button className={membersOpen?'active':''} title={membersOpen?'隐藏成员列表':'显示成员列表'} onClick={()=>setMembersOpen(value=>!value)}><Users size={19}/></button></div></div>
      {(localShare||remoteMedia.some(m=>m.tag==='screen'))&&<MediaStage local={localShare} remote={remoteMedia} members={spaceMembers} onStop={async()=>{await screen.stopShare();localShare?.getTracks().forEach(t=>t.stop());setLocalShare(undefined)}}/>}
      <div ref={messageListRef} className="message-list" onScroll={event=>{const list=event.currentTarget;const atBottom=list.scrollHeight-list.scrollTop-list.clientHeight<72;stickToLatestRef.current=atBottom;setMessageAtBottom(atBottom)}}><div ref={messageFeedRef} className="message-feed"><div className="welcome"><div>{channelIcon(currentChannel?.kind??'text')}</div><h2>欢迎来到 {currentChannel?.name}</h2><p>{currentChannel?.kind==='voice'?'在这里说话、发消息，或者以 1080p / 原画共享你的屏幕。':'这是该频道的起点。开始一段新的对话吧。'}</p></div>{messages.map((m,i)=><Message key={m.id} message={m} compact={messages[i-1]?.userId===m.userId&&m.createdAt-messages[i-1].createdAt<300000} onPreview={(url,name)=>setImagePreview({url,name})}/>)}</div></div>
      {!messageAtBottom&&<button className="message-jump-latest" onClick={()=>{const list=messageListRef.current;if(!list)return;stickToLatestRef.current=true;list.scrollTo({top:list.scrollHeight,behavior:'smooth'});setMessageAtBottom(true)}}><ChevronDown size={15}/>回到最新消息</button>}
      <div className={`composer ${composerExpanded?'expanded':''} ${composerPreview?'previewing':''} ${dropActive?'drop-active':''}`} onDragEnter={event=>{event.preventDefault();setDropActive(true)}} onDragOver={event=>event.preventDefault()} onDragLeave={event=>{if(!event.currentTarget.contains(event.relatedTarget as Node))setDropActive(false)}} onDrop={event=>{event.preventDefault();setDropActive(false);void attach(event.dataTransfer.files?.[0])}}>
        <input ref={fileRef} hidden type="file" onChange={e=>void attach(e.target.files?.[0])}/>
        {composerExpanded&&<div className="composer-toolbar"><button title="粗体" onClick={()=>insertMarkdown('**')}><b>B</b></button><button title="斜体" onClick={()=>insertMarkdown('*')}><i>I</i></button><button title="删除线" onClick={()=>insertMarkdown('~~')}><Strikethrough size={16}/></button><span/><button title="插入链接" onClick={()=>insertMarkdown('[','](https://)','链接文字')}><Link2 size={16}/></button><button title="引用" onClick={()=>prefixMarkdown('> ')}><Quote size={16}/></button><button title="行内代码或代码块" onClick={()=>{const selected=body.slice(composerInputRef.current?.selectionStart??0,composerInputRef.current?.selectionEnd??0);insertMarkdown(selected.includes('\n')?'```\n':'`',selected.includes('\n')?'\n```':'`','代码')}}><Code2 size={16}/></button><button className={composerPreview?'active':''} title={composerPreview?'返回编辑':'预览 Markdown'} onClick={()=>setComposerPreview(value=>!value)}><Eye size={16}/></button></div>}
        {pendingScreenshot&&<div className="composer-pending"><img src={pendingScreenshot.url}/><span><b>{pendingScreenshot.file.name}</b><small>{formatBytes(pendingScreenshot.file.size)} · 等待发送</small></span><button title="移除截图" onClick={()=>setPendingScreenshot(undefined)}><X size={15}/></button></div>}
        <button className="composer-attach" disabled={uploading} onClick={()=>fileRef.current?.click()} title="发送图片或文件">{uploading?<span className="upload-spinner"/>:<CirclePlus size={21}/>}</button>
        {composerPreview?<MarkdownContent body={body||'*没有可预览的内容*'} className="composer-markdown-preview"/>:<textarea ref={composerInputRef} maxLength={4000} value={body} onChange={e=>setBody(e.target.value)} onPaste={event=>{const file=event.clipboardData.files?.[0];if(file){event.preventDefault();void attach(file)}}} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();void send()}}} placeholder={uploading?'正在上传附件…':`发送消息到 #${currentChannel?.name??''}`}/>}
        <button className={emojiOpen?'active':''} title="选择表情" onClick={()=>setEmojiOpen(value=>!value)}><Smile size={20}/></button>
        <button title="区域截图" onClick={()=>void captureScreenshot()}><Scissors size={19}/></button>
        <button title={composerExpanded?'收起编辑器':'展开编辑器'} onClick={()=>{setComposerExpanded(value=>!value);setComposerPreview(false)}}>{composerExpanded?<Minimize2 size={19}/>:<Maximize2 size={19}/>}</button>
        {(composerExpanded||pendingScreenshot)&&<button className="composer-send" disabled={uploading||(!body.trim()&&!pendingScreenshot)} onClick={()=>void send()}><Send size={16}/><span>发送</span></button>}
        {emojiOpen&&<EmojiPicker onPick={emoji=>{setBody(value=>value+emoji);setEmojiOpen(false)}}/>}{dropActive&&<div className="composer-drop"><Image/><b>松开发送文件</b><span>支持图片和最大 50 MB 的文件</span></div>}
      </div>
    </main>
    <aside className="member-panel">{currentChannel?.kind==='voice'?<><div className="member-title">频道成员 — {visibleVoiceMembers.length}</div>{visibleVoiceMembers.map(member=><MemberRow key={member.id} member={member} online status={`已进入 ${currentChannel.name}`}/>)}</>:<><div className="member-title">在线 — {onlineMembers.length}</div>{onlineMembers.map(member=><MemberRow key={member.id} member={member} online status={member.role==='owner'?'社区拥有者':'在线'}/>)}<div className="member-title muted">离线 — {offlineMembers.length}</div>{offlineMembers.map(member=><MemberRow key={member.id} member={member} status={member.role==='owner'?'社区拥有者':'离线'}/>)}</>}<button className="invite-member" onClick={()=>void openInvite()}><UserPlus size={15}/>邀请好友加入</button></aside>
    {spaceDialog&&<SpaceDialog initialMode={spaceDialog} onCreate={createSpaceFromDialog} onJoin={joinSpaceFromDialog} onClose={()=>setSpaceDialog(undefined)}/>} {channelDialog&&<ChannelDialog kind={channelDialog} onCreate={addChannel} onClose={()=>setChannelDialog(undefined)}/>} {invite&&<InviteDialog invite={invite} onClose={()=>setInvite(undefined)}/>} {imagePreview&&<ImagePreview url={imagePreview.url} name={imagePreview.name} onClose={()=>setImagePreview(undefined)}/>} {screenshot&&<ScreenshotSelector capture={screenshot} onConfirm={queueScreenshot} onClose={()=>setScreenshot(undefined)}/>}
    {shareOpen&&<SharePicker sources={sources} profile={shareProfile} setProfile={setShareProfile} includeAudio={shareAudio} setIncludeAudio={setShareAudio} onPick={startShare} onClose={()=>setShareOpen(false)}/>} {settingsOpen&&<AudioSettings connected={!!voiceChannel} devices={audioDevices} busy={settingsBusy} micLevel={muted?0:micLevel} onRefresh={loadAudioDevices} onSelect={async(kind,index)=>{setSettingsBusy(true);try{const mumble=electronBridge().mumble;setAudioDevices(kind==='input'?await mumble.setInput(index):await mumble.setOutput(index))}catch(e){showError(e)}finally{setSettingsBusy(false)}}} onClose={()=>setSettingsOpen(false)}/>} {updateDialogOpen&&<UpdateDialog status={updateStatus} onClose={()=>setUpdateDialogOpen(false)} onDownload={()=>void window.echodeck?.update.download()} onInstall={()=>void window.echodeck?.update.install()} onRetry={()=>void window.echodeck?.update.check()}/>} {error&&<div className="toast">{error}</div>}
  </div>
}

function Auth({onAuth,onError}:{onAuth:(v:AuthPayload)=>void;onError:(e:unknown)=>void}){const[registering,setRegistering]=useState(false);const[username,setUsername]=useState('');const[password,setPassword]=useState('');const[busy,setBusy]=useState(false);const submit=async()=>{setBusy(true);try{onAuth(await request<AuthPayload>(registering?'auth:register':'auth:login',{username,password}))}catch(e){onError(e)}finally{setBusy(false)}};return <div className="auth-page"><div className="aurora a"/><div className="aurora b"/><div className="auth-brand"><div className="brand-mark">POIO</div><h1>POIO</h1><p>一起开黑，清晰沟通，瞬间分享。</p><div className="feature-row"><span><Volume2/>10ms Opus 语音</span><span><MonitorUp/>原画屏幕共享</span><span><Gamepad2/>为游戏而生</span></div></div><div className="auth-card"><h2>{registering?'创建你的账号':'欢迎回来'}</h2><p>{registering?'加入你的第一座语音社区':'登录后继续和朋友一起玩'}</p><label>用户名<input value={username} onChange={e=>setUsername(e.target.value)} placeholder="2–20 位字符"/></label><label>密码<input type="password" value={password} onChange={e=>setPassword(e.target.value)} onKeyDown={e=>{if(e.key==='Enter')void submit()}} placeholder={registering?'至少 8 位':'输入密码'}/></label><button className="primary" disabled={busy} onClick={submit}>{busy?'正在连接…':registering?'注册并开始':'登录'}</button><div className="auth-switch">{registering?'已有账号？':'第一次使用？'}<button onClick={()=>setRegistering(v=>!v)}>{registering?'返回登录':'免费注册'}</button></div></div></div>}
function SpaceDialog({initialMode,onCreate,onJoin,onClose}:{initialMode:'create'|'join';onCreate:(name:string)=>Promise<void>;onJoin:(code:string)=>Promise<void>;onClose:()=>void}){const[mode,setMode]=useState(initialMode);const[value,setValue]=useState('');const[busy,setBusy]=useState(false);const submit=async()=>{if(!value.trim())return;setBusy(true);try{if(mode==='create')await onCreate(value.trim());else await onJoin(value.trim())}finally{setBusy(false)}};return <div className="modal-backdrop"><div className="space-modal"><div className="modal-head"><div><h2>{mode==='join'?'加入一个社区':'创建你的社区'}</h2><p>{mode==='join'?'输入好友发给你的 POIO 邀请码。':'创建后即可邀请好友加入语音频道。'}</p></div><button onClick={onClose}><X/></button></div><div className="space-mode"><button className={mode==='join'?'active':''} onClick={()=>{setMode('join');setValue('')}}><LogIn/>加入社区</button><button className={mode==='create'?'active':''} onClick={()=>{setMode('create');setValue('')}}><Plus/>创建社区</button></div><label>{mode==='join'?'邀请码':'社区名称'}<input autoFocus value={value} maxLength={32} onChange={event=>setValue(mode==='join'?event.target.value.toUpperCase():event.target.value)} onKeyDown={event=>{if(event.key==='Enter')void submit()}} placeholder={mode==='join'?'例如 A1B2C3D4E5':'给社区起个名字'}/></label><button className="primary" disabled={busy||!value.trim()} onClick={()=>void submit()}>{busy?'请稍候…':mode==='join'?'加入社区':'创建社区'}</button></div></div>}
function ChannelDialog({kind,onCreate,onClose}:{kind:'text'|'voice';onCreate:(name:string,kind:'text'|'voice')=>Promise<void>;onClose:()=>void}){const[name,setName]=useState('');const[busy,setBusy]=useState(false);const submit=async()=>{const value=name.trim();if(!value)return;setBusy(true);try{await onCreate(value,kind)}finally{setBusy(false)}};return <div className="modal-backdrop"><div className="channel-modal"><div className="modal-head"><div><h2>创建{kind==='voice'?'语音':'文字'}频道</h2><p>{kind==='voice'?'成员可以在频道内语音、聊天和共享屏幕。':'为社区创建一个新的聊天空间。'}</p></div><button onClick={onClose}><X/></button></div><label>频道名称<input autoFocus value={name} maxLength={32} onChange={event=>setName(event.target.value)} onKeyDown={event=>{if(event.key==='Enter')void submit()}} placeholder={kind==='voice'?'例如：游戏大厅':'例如：攻略交流'}/></label><button className="primary" disabled={busy||!name.trim()} onClick={()=>void submit()}>{busy?'正在创建…':'创建频道'}</button></div></div>}
function InviteDialog({invite,onClose}:{invite:{code:string;spaceName:string;expiresAt:number};onClose:()=>void}){const[copied,setCopied]=useState(false);const copy=async()=>{await navigator.clipboard.writeText(invite.code);setCopied(true);window.setTimeout(()=>setCopied(false),1600)};return <div className="modal-backdrop"><div className="invite-modal"><div className="modal-head"><div><h2>邀请好友加入</h2><p>让好友在 POIO 左侧“＋”中选择“加入社区”。</p></div><button onClick={onClose}><X/></button></div><div className="invite-community"><UserPlus/><div><span>邀请加入</span><b>{invite.spaceName}</b></div></div><div className="invite-code"><code>{invite.code}</code><button onClick={()=>void copy()}>{copied?<Check/>:<Copy/>}{copied?'已复制':'复制邀请码'}</button></div><small>邀请码有效期至 {new Date(invite.expiresAt).toLocaleDateString('zh-CN')}。不要公开发送到陌生群聊。</small></div></div>}
function EmojiPicker({onPick}:{onPick:(emoji:string)=>void}){return <div className="emoji-picker">{['😀','😂','😍','😎','😭','😡','👍','👎','🎉','🔥','❤️','✅','🤔','👀','🙏','💯'].map(emoji=><button key={emoji} onClick={()=>onPick(emoji)}>{emoji}</button>)}</div>}
function updateStatusText(status:AppUpdateStatus){if(status.state==='checking')return '正在检查新版本…';if(status.state==='available')return `发现 ${status.version??'新版本'}，准备下载`;if(status.state==='downloading')return `正在后台下载 ${status.percent??0}%`;if(status.state==='downloaded')return `${status.version??'新版本'} 已下载完成`;if(status.state==='up-to-date')return '当前已是最新版';if(status.state==='error')return status.message??'更新检查失败';if(status.state==='development')return '正式安装版支持在线更新';return '启动后自动检查更新'}
function UpdateDialog({status,onClose,onDownload,onInstall,onRetry}:{status:AppUpdateStatus;onClose:()=>void;onDownload:()=>void;onInstall:()=>void;onRetry:()=>void}){const percent=Math.max(0,Math.min(100,status.percent??0));const downloading=status.state==='downloading';const downloaded=status.state==='downloaded';const failed=status.state==='error';return <div className="modal-backdrop update-backdrop" onClick={onClose}><section className="update-modal" role="dialog" aria-modal="true" aria-label="POIO 客户端更新" onClick={event=>event.stopPropagation()}><button className="update-close" title="稍后处理" onClick={onClose}><X/></button><div className={`update-orb ${downloaded?'done':failed?'failed':''}`}>{downloaded?<Check/>:<Download/>}</div><div className="update-version"><span>POIO 客户端更新</span><b>{status.version?`v${status.version}`:'检查新版本'}</b></div><h2>{downloaded?'更新已准备就绪':downloading?'正在下载更新':failed?'更新遇到问题':'发现新版本'}</h2><p className="update-summary">{downloaded?'安装时 POIO 会重新启动，请先保存正在进行的工作。':downloading?'下载会在后台继续，你可以暂时关闭这个窗口。':failed?(status.message??'暂时无法完成更新，请稍后重试。'):'新版本已经准备好，确认后开始下载。'}</p>{!failed&&<div className="update-notes"><b>本次更新</b><p>{status.notes??'优化 POIO 桌面端体验、稳定性与在线更新流程。'}</p></div>}{(downloading||downloaded)&&<div className="update-progress"><div><span>{downloaded?'下载并校验完成':'正在下载安装包'}</span><b>{downloaded?100:percent}%</b></div><i><em style={{width:`${downloaded?100:percent}%`}}/></i></div>}<footer><button className="secondary" onClick={onClose}>{downloading?'后台下载':'稍后更新'}</button>{status.state==='available'&&<button className="primary" onClick={onDownload}><Download/>下载更新</button>}{downloading&&<button className="primary" disabled><span className="update-spinner"/>正在下载</button>}{downloaded&&<button className="primary ready" onClick={onInstall}><Check/>重启并安装</button>}{failed&&<button className="primary" onClick={onRetry}>重新检查</button>}</footer><small>更新安装包由 POIO 更新服务提供，下载完成后将由客户端自动校验。</small></section></div>}
function ChannelGroup({title,onAdd,children}:{title:string;onAdd:()=>void;children:any}){return <section><div className="group-title"><span><ChevronDown size={13}/>{title}</span><button onClick={onAdd}><Plus size={16}/></button></div>{children}</section>}
function ChannelItem({channel,active,voice,joining,unread,onClick}:{channel:Channel;active:boolean;voice:boolean;joining:boolean;unread:number;onClick:()=>void}){return <button className={`channel ${active?'active':''}`} onClick={onClick}>{channelIcon(channel.kind)}<span>{channel.name}</span>{voice?<i className="voice-pill">已连接</i>:joining?<i className="voice-joining-pill">连接中</i>:unread>0&&<i className="unread-pill">{unread>99?'99+':unread}</i>}</button>}
function MemberRow({member,online=false,status}:{member:User&{role?:string};online?:boolean;status:string}){return <div className={`member ${online?'':'offline'}`}><Avatar name={member.username} avatarUrl={member.avatarUrl}/><div><b>{member.username}{member.role==='owner'&&<Crown size={11}/>}</b><span>{status}</span></div>{online&&<span className="online-dot"/>}</div>}
function VoiceMember({user,self,connected,talking,volume,onVolume}:{user:User;self:boolean;connected:boolean;talking:boolean;volume:number;onVolume:(value:number)=>void}){return <div className={`voice-member ${talking?'speaking':''}`}><Avatar name={user.username} avatarUrl={user.avatarUrl}/><span>{user.username}{self?'（你）':''}</span>{talking&&<i className="talking-wave"><b/><b/><b/></i>}{self?<Mic size={13}/>:<div className="member-volume-wrap"><button disabled={!connected} title={connected?`调节 ${user.username} 的音量`:'加入该频道后可调节音量'}>{volume===0?<VolumeX size={13}/>:<Volume2 size={13}/>}</button>{connected&&<div className="member-volume-popover"><div><span><Volume2 size={14}/>{user.username}</span><b>{volume}%</b></div><input className="volume-range" type="range" min="0" max="200" value={volume} onChange={event=>onVolume(Number(event.target.value))}/><footer><span>仅调整你听到的音量</span><button onClick={()=>onVolume(100)}>重置 100%</button></footer></div>}</div>}</div>}
function AudioControlPopover({kind,volume,devices,onVolume,onDevice,onSettings}:{kind:'input'|'output';volume:number;devices:MumbleAudioDevice[];onVolume:(value:number)=>void;onDevice:(index:number)=>void;onSettings:()=>void}){const input=kind==='input';return <div className="audio-popover"><div className="audio-popover-title"><span>{input?<Mic size={15}/>:<Headphones size={15}/>} {input?'麦克风音量':'耳机音量'}</span><b>{volume}%</b></div><input className="volume-range" type="range" min="0" max={input?100:200} value={volume} onChange={event=>onVolume(Number(event.target.value))}/><label>{input?'输入设备':'输出设备'}<select value={devices.find(device=>device.selected)?.index??''} onChange={event=>onDevice(Number(event.target.value))}>{!devices.length&&<option value="">正在读取设备…</option>}{devices.map(device=><option key={device.index} value={device.index}>{device.name}</option>)}</select></label><button className="audio-settings-link" onClick={onSettings}><Settings size={14}/>语音设置</button></div>}
function Avatar({name,avatarUrl}:{name:string;avatarUrl?:string}){const hue=[...name].reduce((a,c)=>a+c.charCodeAt(0),0)%360;return <div className={`avatar ${avatarUrl?'custom':''}`} style={{background:`linear-gradient(145deg,hsl(${hue} 74% 60%),hsl(${(hue+34)%360} 74% 42%))`}}>{avatarUrl?<img src={`${serverUrl}${avatarUrl}`} alt={name}/>:name.slice(0,1).toUpperCase()}</div>}
function Message({message,compact,onPreview}:{message:ChatMessage;compact:boolean;onPreview:(url:string,name:string)=>void}){const url=message.attachmentUrl?`${serverUrl}${message.attachmentUrl}`:'';const image=message.attachmentMime?.startsWith('image/');return <div className={`message ${compact?'compact':''}`}>{!compact&&<Avatar name={message.username} avatarUrl={message.avatarUrl}/>}<div>{!compact&&<div className="message-meta"><b>{message.username}</b><time>{new Date(message.createdAt).toLocaleString('zh-CN')}</time></div>}{message.body&&<MarkdownContent body={message.body}/>} {url&&(image?<button className="image-attachment" onClick={()=>onPreview(url,message.attachmentName??'图片')}><img src={url}/><span><Image size={13}/>{message.attachmentName}</span></button>:<a className="file-attachment" href={url} target="_blank"><FileText/><span><b>{message.attachmentName}</b><small>{formatBytes(message.attachmentSize??0)}</small></span><Download size={17}/></a>)}</div></div>}
function MarkdownContent({body,className=''}:{body:string;className?:string}){return <div className={`markdown-body ${className}`}><ReactMarkdown remarkPlugins={[remarkGfm]} components={{a:({children,...props})=><a {...props} target="_blank" rel="noreferrer">{children}</a>,pre:({children})=>{const child=Array.isArray(children)?children[0]:children;const text=String((child as any)?.props?.children??'').replace(/\n$/,'');const language=String((child as any)?.props?.className??'').replace(/^language-/,'')||'代码';return <div className="markdown-code"><header><span>{language}</span><button onClick={()=>void navigator.clipboard.writeText(text)}><Copy size={13}/>复制</button></header><pre>{children}</pre></div>}}}>{body}</ReactMarkdown></div>}
function ImagePreview({url,name,onClose}:{url:string;name:string;onClose:()=>void}){return <div className="image-preview-backdrop" onClick={onClose}><div className="image-preview" onClick={event=>event.stopPropagation()}><header><span><Image/><b>{name}</b></span><div><a href={url} target="_blank"><Download/>打开原图</a><button onClick={onClose}><X/></button></div></header><img src={url} alt={name}/></div></div>}
function ScreenshotSelector({capture,onConfirm,onClose}:{capture:ScreenshotCapture;onConfirm:(file:File)=>void;onClose:()=>void}){const imageRef=useRef<HTMLImageElement>(null);const origin=useRef<{x:number;y:number}|undefined>(undefined);const[selection,setSelection]=useState<{x:number;y:number;width:number;height:number}>();const[busy,setBusy]=useState(false);useEffect(()=>{const key=(event:KeyboardEvent)=>{if(event.key==='Escape')onClose()};window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key)},[onClose]);const point=(event:React.PointerEvent<HTMLDivElement>)=>{const rect=event.currentTarget.getBoundingClientRect();return{x:Math.max(0,Math.min(rect.width,event.clientX-rect.left)),y:Math.max(0,Math.min(rect.height,event.clientY-rect.top))}};const move=(event:React.PointerEvent<HTMLDivElement>)=>{if(!origin.current)return;const current=point(event);setSelection({x:Math.min(origin.current.x,current.x),y:Math.min(origin.current.y,current.y),width:Math.abs(current.x-origin.current.x),height:Math.abs(current.y-origin.current.y)})};const confirm=async()=>{const image=imageRef.current;if(!image)return;setBusy(true);try{const rect=image.getBoundingClientRect();const area=selection&&selection.width>=4&&selection.height>=4?selection:{x:0,y:0,width:rect.width,height:rect.height};const scaleX=image.naturalWidth/rect.width;const scaleY=image.naturalHeight/rect.height;const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(area.width*scaleX));canvas.height=Math.max(1,Math.round(area.height*scaleY));canvas.getContext('2d')?.drawImage(image,Math.round(area.x*scaleX),Math.round(area.y*scaleY),canvas.width,canvas.height,0,0,canvas.width,canvas.height);const blob=await new Promise<Blob>((resolve,reject)=>canvas.toBlob(value=>value?resolve(value):reject(new Error('截图生成失败')),'image/png'));const stamp=new Date().toISOString().replace(/[-:]/g,'').replace('T','-').slice(0,15);onConfirm(new File([blob],`POIO截图-${stamp}.png`,{type:'image/png'}))}finally{setBusy(false)}};return <div className="screenshot-backdrop"><div className="screenshot-head"><div><Scissors/><span><b>区域截图</b><small>{capture.displayName} · 拖动鼠标选择范围，按 Esc 取消</small></span></div><div><button onClick={onClose}>取消</button><button className="primary" disabled={busy} onClick={()=>void confirm()}>{busy?'处理中…':selection&&selection.width>=4?'添加到消息':'截取完整屏幕'}</button></div></div><div className="screenshot-workspace"><div className="screenshot-image-wrap"><img ref={imageRef} src={capture.dataUrl}/><div className="screenshot-hit" onPointerDown={event=>{event.currentTarget.setPointerCapture(event.pointerId);const start=point(event);origin.current=start;setSelection({...start,width:0,height:0})}} onPointerMove={move} onPointerUp={event=>{move(event);origin.current=undefined}}>{selection&&<div className="screenshot-selection" style={selection}/>}</div></div></div></div>}
function formatBytes(bytes:number){if(bytes<1024)return `${bytes} B`;if(bytes<1048576)return `${(bytes/1024).toFixed(1)} KB`;return `${(bytes/1048576).toFixed(1)} MB`}
function MediaStage({local,remote,members,onStop}:{local?:MediaStream;remote:RemoteMedia[];members:User[];onStop:()=>void}){return <div className="media-stage">{local&&<VideoTile stream={local} label="你的屏幕" local onStop={onStop}/>} {remote.filter(m=>m.tag==='screen').map(m=><VideoTile key={m.id} stream={m.stream} label={`${members.find(member=>member.id===m.userId)?.username??'成员'} 的屏幕`}/>) } {remote.filter(m=>m.kind==='audio').map(m=><Audio key={m.id} stream={m.stream}/>)}</div>}
function VideoTile({stream,label,local,onStop}:{stream:MediaStream;label:string;local?:boolean;onStop?:()=>void}){const ref=useRef<HTMLVideoElement>(null);const tileRef=useRef<HTMLDivElement>(null);const[fullscreen,setFullscreen]=useState(false);useEffect(()=>{if(ref.current)ref.current.srcObject=stream},[stream]);useEffect(()=>{const changed=()=>setFullscreen(document.fullscreenElement===tileRef.current);document.addEventListener('fullscreenchange',changed);return()=>document.removeEventListener('fullscreenchange',changed)},[]);const toggleFullscreen=async()=>{if(document.fullscreenElement)await document.exitFullscreen();else await tileRef.current?.requestFullscreen()};return <div ref={tileRef} className="video-tile"><video ref={ref} autoPlay playsInline muted={local} onDoubleClick={()=>void toggleFullscreen()}/><span className="video-label">{label}</span><div className="video-actions"><button className="fullscreen-control" title={fullscreen?'退出全屏':'全屏观看'} onClick={()=>void toggleFullscreen()}>{fullscreen?<Minimize2 size={15}/>:<Maximize2 size={15}/>}<span>{fullscreen?'退出全屏':'全屏'}</span></button>{local&&<button className="stop-share" onClick={onStop}><X size={15}/>停止共享</button>}</div></div>}
function Audio({stream}:{stream:MediaStream}){const ref=useRef<HTMLAudioElement>(null);useEffect(()=>{if(ref.current)ref.current.srcObject=stream},[stream]);return <audio ref={ref} autoPlay/>}
function SharePicker({sources,profile,setProfile,includeAudio,setIncludeAudio,onPick,onClose}:{sources:any[];profile:ShareProfile;setProfile:(v:ShareProfile)=>void;includeAudio:boolean;setIncludeAudio:(value:boolean)=>void;onPick:(id:string)=>void;onClose:()=>void}){return <div className="modal-backdrop"><div className="share-modal"><div className="modal-head"><div><h2>共享你的屏幕</h2><p>选择窗口与画质，POIO 会优先保持低延迟。</p></div><button onClick={onClose}><X/></button></div><div className="profiles">{([['smooth','流畅','720p · 30fps'],['hd','高清','1080p · 30fps'],['fps','高帧率','1080p · 60fps'],['original','原画','源分辨率 · 最高60fps']] as const).map(([id,name,detail])=><button className={profile===id?'active':''} onClick={()=>setProfile(id)} key={id}><b>{name}</b><span>{detail}</span></button>)}</div><label className="share-audio-option"><input type="checkbox" checked={includeAudio} onChange={event=>setIncludeAudio(event.target.checked)}/><span><Volume2/><b>共享系统声音</b><small>让观看者同时听到游戏、视频或应用声音；共享整个屏幕时兼容性最好。</small></span></label><div className="source-grid">{sources.map(s=><button key={s.id} onClick={()=>onPick(s.id)}><img src={s.thumbnail}/><span>{s.name}</span></button>)}</div></div></div>}
function AudioSettings({connected,devices,busy,micLevel,onRefresh,onSelect,onClose}:{connected:boolean;devices?:MumbleAudioDevices;busy:boolean;micLevel:number;onRefresh:()=>Promise<void>;onSelect:(kind:'input'|'output',index:number)=>Promise<void>;onClose:()=>void}){
  const [testing,setTesting]=useState(false);
  const [diagnosticsState,setDiagnosticsState]=useState<'idle'|'copying'|'copied'>('idle');
  const input=devices?.inputs.find(d=>d.selected)?.index??'';
  const output=devices?.outputs.find(d=>d.selected)?.index??'';
  const level=testing?Math.max(0,Math.min(1,(micLevel-.18)/.82)):0;
  const copyDiagnostics=async()=>{setDiagnosticsState('copying');try{await navigator.clipboard.writeText(await electronBridge().diagnostics());setDiagnosticsState('copied');window.setTimeout(()=>setDiagnosticsState('idle'),1800)}catch{setDiagnosticsState('idle')}};
  return <div className="modal-backdrop"><div className="settings-modal"><div className="modal-head"><div><h2>语音设置</h2><p>由 Mumble 原生 WASAPI 音频引擎直接管理。</p></div><button onClick={onClose}><X/></button></div>{!connected?<div className="settings-empty"><Headphones/><b>先加入语音频道</b><span>连接后即可读取并切换麦克风和扬声器。</span></div>:<><div className="engine-card"><div className="engine-dot"/><div><b>Mumble Native</b><span>{devices?.inputBackend??'WASAPI'} / {devices?.outputBackend??'WASAPI'} · 低延迟模式</span></div><button disabled={busy} onClick={()=>void onRefresh()}>{busy?'读取中…':'刷新设备'}</button></div><label className="device-field"><span><Mic/>输入设备</span><select disabled={busy||!devices?.inputs.length} value={input} onChange={e=>void onSelect('input',Number(e.target.value))}>{!devices?.inputs.length&&<option value="">未检测到输入设备</option>}{devices?.inputs.map(device=><option value={device.index} key={device.index}>{device.name}</option>)}</select><small>选择用于发送语音的麦克风。</small></label><div className={`mic-test ${testing?'testing':''}`}><div className="mic-test-head"><span><Mic/>麦克风测试</span><button onClick={()=>setTesting(value=>!value)}>{testing?'停止测试':'开始测试'}</button></div><div className="mic-test-track"><i style={{width:`${Math.round(level*100)}%`}}/></div><small>{testing?(level>.25?'已检测到声音，对着麦克风说话时音量条会实时变化。':'正在监听，请对着麦克风说话…'):'点击开始测试，检查麦克风输入音量。'}</small></div><label className="device-field"><span><Volume2/>输出设备</span><select disabled={busy||!devices?.outputs.length} value={output} onChange={e=>void onSelect('output',Number(e.target.value))}>{!devices?.outputs.length&&<option value="">未检测到输出设备</option>}{devices?.outputs.map(device=><option value={device.index} key={device.index}>{device.name}</option>)}</select><small>选择用于播放频道语音的耳机或扬声器。</small></label><p className="settings-note">切换时语音会短暂重启，当前频道连接不会断开。选择结果会由 Mumble 保存。</p></>}<div className="diagnostics-row"><div><b>遇到问题？</b><span>复制不含密码的运行环境和音频核心状态。</span></div><button disabled={diagnosticsState==='copying'} onClick={()=>void copyDiagnostics()}>{diagnosticsState==='copied'?<Check/>:<Copy/>}{diagnosticsState==='copying'?'正在生成…':diagnosticsState==='copied'?'已复制':'复制诊断信息'}</button></div></div></div>
}
